import { test, expect } from '@playwright/test';

test.describe('Notifications', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display empty state when there are no notifications', async ({ page }) => {
    await expect(page.getByText('You have no notifications')).toBeVisible();
  });

  test('should not display any notification items', async ({ page }) => {
    const notificationItems = page.locator('.notification-item');
    await expect(notificationItems).toHaveCount(0);
  });
});
